'use strict';
const MODELS=[{id:'muse',name:'MUSE',resolutions:['auto']},{id:'seedream-5-pro',name:'Seedream 5.0 Pro',resolutions:['1.5k','2k']},{id:'nano-banana-pro',name:'Nano Banana Pro',resolutions:['2k','4k']},{id:'gpt-image-2-5',name:'GPT Image 2.5 Medium',resolutions:['2k','4k']}];
const RATIOS={'1:1':'square_1_1','3:4':'traditional_3_4','9:16':'social_story_9_16','16:9':'widescreen_16_9','4:3':'classic_4_3'};
function validate(body){const model=MODELS.find(m=>m.id===body.model&&m.id!=='muse');if(!model||!model.resolutions.includes(body.resolution))throw Error('Model hoặc độ phân giải không hợp lệ.');if(!RATIOS[body.ratio])throw Error('Tỷ lệ không hợp lệ.');if(!Array.isArray(body.prompts)||!body.prompts.length||body.prompts.length>8||body.prompts.some(p=>typeof p!=='string'||!p.trim()||p.length>20000))throw Error('Chọn 1–8 ảnh với prompt hợp lệ.');if(!Array.isArray(body.refTags)||body.refTags.length>10||body.refTags.some(t=>typeof t!=='string'||!t||t.length>200))throw Error('Chọn tối đa 10 ảnh tham chiếu.');return model}
function estimate(body){validate(body);const n=body.prompts.length;if(body.model==='gpt-image-2-5')return{min:15*n,max:1000*n,kind:'published-range'};const cost=body.model==='nano-banana-pro'?(body.resolution==='4k'?150:75):(body.resolution==='2k'?150:75);return{min:cost*n,max:cost*n,kind:'published-estimate'}}
function buildPayload(body,prompt,refs){validate(body);const gpt=body.model==='gpt-image-2-5',nano=body.model==='nano-banana-pro';const endpoint=nano?'nano-banana-pro':body.model==='seedream-5-pro'?'seedream-v5-pro'+(refs.length?'-edit':''):'gpt-image-2-5'+(refs.length?'-edit':'');const payload={prompt,aspect_ratio:nano?body.ratio:RATIOS[body.ratio],resolution:nano?body.resolution.toUpperCase():body.resolution};if(gpt){payload.quality='medium';payload.num_images=1;payload.output_format='png'}if(refs.length)payload.reference_images=nano?refs.map((r,i)=>({image:r.url,mime_type:r.mime,text:'image '+(i+1)+' = @'+r.tag})):refs.map(r=>r.url);return{endpoint,payload}}
module.exports={MODELS,RATIOS,validate,estimate,buildPayload};
